import React, { useState, useEffect } from 'react';
import { apiGetCampaigns, apiGetCollaborations, apiCreateCampaign, getCurrentUser } from '../services/api';

interface CampaignDashboardProps {
  onNavigate: (target: string, payload?: any) => void;
  onBack: () => void;
}

const CampaignDashboard: React.FC<CampaignDashboardProps> = ({ onNavigate, onBack }) => {
  const currentUser = getCurrentUser();
  const isBrand = currentUser?.userType === 'Brand';

  const [campaigns, setCampaigns] = useState<any[]>([]);
  const [collaborations, setCollaborations] = useState<any[]>([]);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [formData, setFormData] = useState({ title: '', goal: '', budget: '', niche: '' });

  useEffect(() => {
    fetchData();
  }, [isBrand]);

  const fetchData = async () => {
    try {
      if (isBrand) {
        const camps = await apiGetCampaigns();
        setCampaigns(camps);
      }
      const collabs = await apiGetCollaborations();
      setCollaborations(collabs);
    } catch (err) {
      console.error('Failed to load dashboard data', err);
    }
  };

  const handeCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await apiCreateCampaign({ ...formData, requirements: ['Content Draft'] });
      setShowCreateModal(false);
      setFormData({ title: '', goal: '', budget: '', niche: '' });
      fetchData();
    } catch (err) {
      alert('Failed to create campaign');
    }
  };

  return (
    <div className="flex flex-col h-full bg-base-bg text-base-text transition-colors duration-300">
      <header className="flex items-center justify-between p-4 border-b border-white/10 shrink-0">
        <button onClick={onBack} className="text-brand-magenta font-semibold"> Back </button>
        <h1 className="text-xl font-bold">Campaign Dashboard</h1>
        {isBrand ? (
          <button onClick={() => setShowCreateModal(true)} className="px-4 py-2 bg-brand-magenta text-white rounded-lg">
            Create Campaign
          </button>
        ) : <div className="w-12" />}
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-8">
        {isBrand && (
          <section>
            <h2 className="text-xl font-bold mb-4">My Campaigns</h2>
            <div className="grid gap-4">
              {campaigns.length === 0 ? (
                <p className="text-white/50">No campaigns created yet.</p>
              ) : (
                campaigns.map(camp => (
                  <div key={camp._id} className="p-4 bg-white/5 border border-white/10 rounded-xl cursor-pointer hover:bg-white/10 transition-colors"
                       onClick={() => onNavigate('campaign-details', camp._id)}>
                    <h3 className="font-bold text-lg">{camp.title}</h3>
                    <p className="text-sm text-white/70">Goal: {camp.goal}</p>
                    <p className="text-sm text-brand-cyan">Budget: ${camp.budget || 0}</p>
                  </div>
                ))
              )}
            </div>
          </section>
        )}

        <section>
          <h2 className="text-xl font-bold mb-4">Active Collaborations</h2>
          <div className="grid gap-4">
            {collaborations.length === 0 ? (
              <p className="text-white/50">No active collaborations.</p>
            ) : (
              collaborations.map(collab => (
                <div key={collab._id} className="p-4 bg-white/5 border border-white/10 rounded-xl">
                  <h3 className="font-bold text-lg">{collab.campaignId?.title || 'Unknown Campaign'}</h3>
                  <p className="text-sm text-white/70">
                    Partner: {isBrand ? collab.influencerId?.displayName : collab.brandId?.displayName}
                  </p>
                  <div className="mt-2 inline-block px-3 py-1 bg-white/10 rounded-full text-xs">
                    {collab.status}
                  </div>
                </div>
              ))
            )}
          </div>
        </section>
      </main>

      {/* Create Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm px-4">
          <div className="bg-base-bg w-full max-w-md rounded-2xl border border-white/10 p-6">
            <h2 className="text-2xl font-bold mb-4">Create Campaign</h2>
            <form onSubmit={handeCreate} className="space-y-4">
              <input type="text" placeholder="Campaign Title" required className="w-full px-4 py-3 bg-white/5 border border-white/20 rounded-xl"
                     value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} />
              <input type="text" placeholder="Goal (e.g., Brand Awareness)" required className="w-full px-4 py-3 bg-white/5 border border-white/20 rounded-xl"
                     value={formData.goal} onChange={e => setFormData({...formData, goal: e.target.value})} />
              <input type="number" placeholder="Budget ($)" className="w-full px-4 py-3 bg-white/5 border border-white/20 rounded-xl"
                     value={formData.budget} onChange={e => setFormData({...formData, budget: e.target.value})} />
              <input type="text" placeholder="Niche" className="w-full px-4 py-3 bg-white/5 border border-white/20 rounded-xl"
                     value={formData.niche} onChange={e => setFormData({...formData, niche: e.target.value})} />
              <div className="flex justify-end gap-2 mt-4">
                <button type="button" onClick={() => setShowCreateModal(false)} className="px-4 py-2 hover:bg-white/10 rounded-lg">Cancel</button>
                <button type="submit" className="px-4 py-2 bg-brand-cyan hover:bg-brand-cyan/90 text-black font-semibold rounded-lg">Create</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CampaignDashboard;
